-- Collector's Ledger (part of Comprehensive Objective Mod)
-- Browse the best items that are placed in the world (loose or fixed container contents),
-- ranked with the live records, and track the nearest copy in the objective panel
-- (events CO_SetCustomBlock / CO_RemoveCustomBlock handled by player.lua).
-- Data: ledger_data.lua (generated by tools/build_ledger.py).
local core = require('openmw.core')
local self = require('openmw.self')
local types = require('openmw.types')
local ui = require('openmw.ui')
local util = require('openmw.util')
local input = require('openmw.input')
local nearby = require('openmw.nearby')
local async = require('openmw.async')
local storage = require('openmw.storage')
local I = require('openmw.interfaces')

local L10N = 'CollectorsLedger'
local TRIGGER = 'CL_ToggleLedger'
local BINDING_ID = 'CL_ToggleLedger_binding'
local BLOCK_ID = 'ledger'
local BLOCK_NAME = "Collector's Ledger"
local BLOCK_COLOR = { 0.95, 0.78, 0.35 }

