-- data
---------------------------------------------------------------------------
local okData, DATA = pcall(require, 'scripts.comprehensive_objectives.ledger_data')
if not okData or type(DATA) ~= 'table' then
    print("[Collector's Ledger] no data: " .. tostring(DATA))
    DATA = { plugins = {}, cells = {}, items = {}, sets = {} }
end
local ITEMS, CELLS, PLUGINS = DATA.items or {}, DATA.cells or {}, DATA.plugins or {}

local CELL_BY_ID = {}
for i, c in ipairs(CELLS) do
    if c.id then CELL_BY_ID[c.id] = i end
end

local LOADED = {}
pcall(function()
    for _, f in ipairs(core.contentFiles.list) do LOADED[f:lower()] = true end
end)
local function pluginLoaded(p)
    local name = PLUGINS[p]
    if not name then return true end
    if next(LOADED) == nil then return true end
    return LOADED[name:lower()] == true
end

