---------------------------------------------------------------------------
-- small helpers
---------------------------------------------------------------------------
local function hasFlag(f, b) return math.floor((f or 0) / b) % 2 == 1 end
local function lower(s) return s and tostring(s):lower() or '' end
local function clamp(x, a, b) if x < a then return a elseif x > b then return b end return x end
local function fmt(x) return string.format('%.1f', x or 0) end
local function gmst(name, dflt)
    local ok, v = pcall(core.getGMST, name)
    if ok and type(v) == 'number' then return v end
    return dflt
end

local TYPES = {
    WEAP = types.Weapon, ARMO = types.Armor, CLOT = types.Clothing, BOOK = types.Book, INGR = types.Ingredient,
}
local recCache = {}
local function getRecord(t, id)
    local key = t .. '|' .. id
    local c = recCache[key]
    if c ~= nil then return c or nil end
    local T = TYPES[t]
    local r
    if T then
        local ok, v = pcall(function() return T.records[id] end)
        if ok and v then r = v else
            ok, v = pcall(T.record, id)
            if ok then r = v end
        end
    end
    recCache[key] = r or false
    return r
end

---------------------------------------------------------------------------
-- sources (placements) of an item
---------------------------------------------------------------------------
local stale = {}     -- saved: source key -> true (verified missing)
local function srcKey(id, s)
    local c = CELLS[s.cell]
    return id .. '@' .. ((c and c.id) or 'e') .. '@' .. s.x .. ',' .. s.y
end

local function sourcesOf(id)
    local it = ITEMS[id]
    if not it then return {} end
    if it._S then return it._S end
    local out = {}
    for rec in (it.L or ''):gmatch('[^;]+') do
        local c, x, y, z, f, lock, p, cont = rec:match('^(%d+),(%-?%d+),(%-?%d+),(%-?%d+),(%d+),(%-?%d+),(%d+),(.*)$')
        if c then
            local fl = tonumber(f)
            out[#out + 1] = {
                cell = tonumber(c), x = tonumber(x), y = tonumber(y), z = tonumber(z), flags = fl,
                lock = tonumber(lock), plugin = tonumber(p), cont = cont,
                owned = hasFlag(fl, 1), trapped = hasFlag(fl, 2), inCont = hasFlag(fl, 4),
                plant = hasFlag(fl, 8), respawn = hasFlag(fl, 16), body = hasFlag(fl, 32),
            }
        end
    end
    it._S = out
    return out
end

local doorCache = {}
local function cellDoors(ci)
    if doorCache[ci] then return doorCache[ci] end
    local out = {}
    local c = CELLS[ci]
    for d in ((c and c.D) or ''):gmatch('[^;]+') do
        local cc, x, y, z = d:match('^(%w+),(%-?%d+),(%-?%d+),(%-?%d+)$')
        if cc then
            out[#out + 1] = { ext = (cc == 'e'), cell = tonumber(cc), x = tonumber(x), y = tonumber(y), z = tonumber(z) }
        end
    end
    doorCache[ci] = out
    return out
end

-- outdoor point of a cell (exterior: nil, interior: first outdoor route door)
local function cellAnchor(ci)
    for _, d in ipairs(cellDoors(ci)) do
        if d.ext then return d.x, d.y end
    end
    return nil
end

local function srcAnchor(s)
    local c = CELLS[s.cell]
    if not c then return nil end
    if c.e then return s.x, s.y end
    return cellAnchor(s.cell)
end

local function visibleSources(id)
    local out = {}
    for _, s in ipairs(sourcesOf(id)) do
        if pluginLoaded(s.plugin) and not stale[srcKey(id, s)] and CELLS[s.cell] then out[#out + 1] = s end
    end
    return out
end

---------------------------------------------------------------------------
-- where is the player (outdoor coordinates)
---------------------------------------------------------------------------
local lastExt   -- saved {x,y}
local function playerAnchor()
    local cell = self.cell
    if not cell then return nil end
    if cell.isExterior then return self.position.x, self.position.y end
    local bx, by
    pcall(function()
        for _, d in ipairs(nearby.doors) do
            if types.Door.isTeleport(d) then
                local dc = types.Door.destCell(d)
                if dc and dc.isExterior then
                    local p = types.Door.destPosition(d)
                    bx, by = p.x, p.y
                    return
                end
            end
        end
    end)
    if bx then return bx, by end
    local ci = CELL_BY_ID[lower(cell.id)] or CELL_BY_ID[lower(cell.name)]
    if ci then
        local x, y = cellAnchor(ci)
        if x then return x, y end
    end
    if lastExt then return lastExt.x, lastExt.y end
    return nil
end

local function distCells(d)
    if not d then return '?' end
    return string.format('%.1f cells', d / 8192)
end

-- nearest visible source; preferFree: unowned + unlocked first (ingredients)
local function nearestSource(id, preferFree)
    local list = visibleSources(id)
    local px, py = playerAnchor()
    local best, bestD, bestFree, bestFreeD
    for _, s in ipairs(list) do
        local ax, ay = srcAnchor(s)
        local d = 1e12
        if ax and px then d = math.sqrt((ax - px) ^ 2 + (ay - py) ^ 2)
        elseif ax then d = 1e11 end
        if not best or d < bestD then best, bestD = s, d end
        if not s.owned and (s.lock or 0) <= 0 and not s.trapped then
            if not bestFree or d < bestFreeD then bestFree, bestFreeD = s, d end
        end
    end
    if preferFree and bestFree then best, bestD = bestFree, bestFreeD end
    if bestD and bestD >= 1e11 then bestD = nil end
    return best, bestD, #list
end

local function whereText(s)
    local c = CELLS[s.cell]
    if not c then return '?' end
    local t = c.n or '?'
    if c.e then
        t = t .. string.format(' [%d,%d]', math.floor(s.x / 8192), math.floor(s.y / 8192))
    elseif c.near and c.near ~= '' and c.near ~= c.n then
        t = t .. ', near ' .. c.near
    end
    if s.body then t = t .. ' - on the ' .. (s.cont or 'body')
    elseif s.cont and s.cont ~= '' then t = t .. ' - in ' .. s.cont else t = t .. ' - lying loose' end
    return t
end

local function tagText(s, pluginIdx)
    local tags = {}
    if s.owned then tags[#tags + 1] = 'OWNED (stealing)' end
    if (s.lock or 0) > 0 then tags[#tags + 1] = 'locked ' .. s.lock end
    if s.trapped then tags[#tags + 1] = 'trapped' end
    local c = CELLS[s.cell]
    if c and not c.e then
        tags[#tags + 1] = 'interior'
        if not cellAnchor(s.cell) then tags[#tags + 1] = 'no door from outside' end
    end
    if s.plant then tags[#tags + 1] = 'plant' end
    if s.body then tags[#tags + 1] = 'on a body' end
    if s.respawn then tags[#tags + 1] = 'respawns' end
    local p = PLUGINS[pluginIdx or s.plugin]
    if p then tags[#tags + 1] = p end
    return table.concat(tags, ', ')
end

local function markerFor(id, s)
    local c = CELLS[s.cell]
    local function cellOf(ci, ext)
        if ext then return { isExterior = true } end
        local cc = CELLS[ci]
        return { isExterior = false, id = cc and cc.id or '' }
    end
    local positions = { { cell = cellOf(s.cell, c and c.e), position = { x = s.x, y = s.y, z = s.z } } }
    if c and not c.e then
        for _, d in ipairs(cellDoors(s.cell)) do
            positions[#positions + 1] = { cell = cellOf(d.cell, d.ext), position = { x = d.x, y = d.y, z = d.z }, door = true }
        end
    end
    return { positions = positions }
end

---------------------------------------------------------------------------
-- scoring (live records)
---------------------------------------------------------------------------
local CLS
local MAGIC_SKILLS = { destruction = true, alteration = true, illusion = true, conjuration = true,
                       mysticism = true, restoration = true, enchant = true }
local function classInfo()
    if CLS then return CLS end
    local c = { major = {}, minor = {}, attrs = {}, spec = 'combat', magic = false, name = '?' }
    pcall(function()
        local rec = types.NPC.record(self)
        local cr = types.NPC.classes.records[rec.class]
        c.name = cr.name or rec.class
        for _, s in ipairs(cr.majorSkills) do c.major[lower(s)] = true end
        for _, s in ipairs(cr.minorSkills) do c.minor[lower(s)] = true end
        for _, a in ipairs(cr.attributes) do c.attrs[lower(a)] = true end
        c.spec = lower(cr.specialization)
    end)
    for s in pairs(c.major) do if MAGIC_SKILLS[s] then c.magic = true end end
    for s in pairs(c.minor) do if MAGIC_SKILLS[s] then c.magic = true end end
    CLS = c
    return c
end

-- utility effects that rarely matter for picking gear: counted, but at a fraction
local LOW_VALUE = { resistcommondisease = 0.3, resistblightdisease = 0.3, resistcorprusdisease = 0.3, swiftswim = 0.3,
                    waterbreathing = 0.3, waterwalking = 0.4, detectanimal = 0.3, detectenchantment = 0.3, detectkey = 0.3,
                    nighteye = 0.4, light = 0.3, telekinesis = 0.4, slowfall = 0.5, feather = 0.6, jump = 0.6 }

local function classWeight(eid, eff)
    if LOW_VALUE[eid] then return LOW_VALUE[eid] end
    local c = classInfo()
    if eid == 'fortifyskill' or eid == 'restoreskill' or eid == 'absorbskill' then
        local s = lower(eff.affectedSkill)
        if c.major[s] then return 1.6 end
        if c.minor[s] then return 1.25 end
        return 0.6
    end
    if eid == 'fortifyattribute' or eid == 'restoreattribute' or eid == 'absorbattribute' then
        local a = lower(eff.affectedAttribute)
        if c.attrs[a] then return 1.5 end
        if (a == 'intelligence' or a == 'willpower') and c.spec == 'combat' then return 0.7 end
        return 1.0
    end
    if eid == 'fortifymagicka' or eid == 'fortifymaximummagicka' or eid == 'restoremagicka' or eid == 'spellabsorption' then
        if c.spec == 'magic' then return 1.2 end
        return c.magic and 0.85 or 0.6
    end
    if eid == 'fortifyattack' or eid == 'fortifyhealth' or eid == 'fortifyfatigue' or eid == 'restorehealth'
        or eid == 'restorefatigue' then
        return c.spec == 'combat' and 1.3 or 1.0
    end
    return 1.0
end

local RANGE_TARGET
pcall(function() RANGE_TARGET = core.magic.RANGE.Target end)
local ET = {}
pcall(function() ET = core.magic.ENCHANTMENT_TYPE end)

local MAG_CAP = 100
-- OpenMW enchanting cost (Enchanting::getEnchantPoints), per effect
local function effectCost(eff, constant)
    local mg = eff.effect
    if not mg then pcall(function() mg = core.magic.effects.records[eff.id] end) end
    local base = (mg and mg.baseCost) or 1
    -- magnitudes above 100 add nothing useful (100% resist, 100 pt drains) and would swamp the ranking
    local mn = clamp(eff.magnitudeMin or 0, 1, MAG_CAP)
    local mx = clamp(eff.magnitudeMax or 0, 1, MAG_CAP)
    local area = math.max(1, eff.area or 0)
    local dur = eff.duration or 0
    if constant then
        dur = gmst('fEnchantmentConstantDurationMult', 100)
    elseif mg and mg.hasDuration == false then
        dur = 1
    else
        dur = math.max(1, dur)
    end
    local cost = ((mn + mx) * dur + area) * base * gmst('fEffectCostMult', 0.5) * 0.05
    cost = math.max(1, cost)
    if RANGE_TARGET ~= nil and eff.range == RANGE_TARGET then cost = cost * 1.5 end
    return cost, mg
end

local function effectLabel(eff, mg)
    local n = (mg and mg.name) or tostring(eff.id)
    local extra = eff.affectedSkill or eff.affectedAttribute
    if extra then n = n .. ' ' .. tostring(extra) end
    local mx = eff.magnitudeMax or 0
    if mx > 0 and (not mg or mg.hasMagnitude ~= false) then n = n .. ' ' .. mx end
    return n
end

-- score of a list of effects (enchantment or spell); returns total, short label
local function effectsScore(effects, constant)
    local total, best, bestLabel = 0, -1, ''
    local n = 0
    for _, eff in ipairs(effects or {}) do
        local c, mg = effectCost(eff, constant)
        local eid = lower(eff.id)
        local w = classWeight(eid, eff)
        local v = c * w
        if constant and mg and mg.harmful then v = -v end
        total = total + v
        n = n + 1
        if math.abs(v) > best then
            best = math.abs(v)
            bestLabel = effectLabel(eff, mg) .. (w ~= 1 and (' x' .. w) or '')
        end
    end
    if n > 1 then bestLabel = bestLabel .. ' +' .. (n - 1) end
    return total, bestLabel
end

local function enchantScore(enchId, isScroll)
    if not enchId or enchId == '' then return 0, nil end
    local e
    pcall(function() e = core.magic.enchantments.records[enchId] end)
    if not e then return 0, nil end
    local constant = (e.type == ET.ConstantEffect)
    local total, label = effectsScore(e.effects, constant)
    local mult, kind
    if constant then
        mult, kind = 1, 'Constant'
    elseif e.type == ET.CastOnStrike then
        local uses = (e.charge or 0) / math.max(1, e.cost or 1)
        mult, kind = 0.5 * clamp(math.sqrt(uses / 20), 0.25, 1.25), 'On strike'
    elseif e.type == ET.CastOnUse then
        local uses = (e.charge or 0) / math.max(1, e.cost or 1)
        mult, kind = 0.3 * clamp(math.sqrt(uses / 10), 0.25, 1.25), 'When used'
    else
        mult, kind = isScroll and 1 or 0, 'Cast once'
    end
    return total * mult, kind .. ': ' .. label
end

local ENCH_WEIGHT = 0.5

local WT = types.Weapon.TYPE
local WEAPON_CAT = {}
local RANGED = {}
pcall(function()
    WEAPON_CAT[WT.ShortBladeOneHand] = 'shortblade'
    WEAPON_CAT[WT.LongBladeOneHand] = 'longblade'
    WEAPON_CAT[WT.LongBladeTwoHand] = 'longblade'
    WEAPON_CAT[WT.BluntOneHand] = 'blunt'
    WEAPON_CAT[WT.BluntTwoClose] = 'blunt'
    WEAPON_CAT[WT.BluntTwoWide] = 'blunt'
    WEAPON_CAT[WT.SpearTwoWide] = 'spear'
    WEAPON_CAT[WT.AxeOneHand] = 'axe'
    WEAPON_CAT[WT.AxeTwoHand] = 'axe'
    WEAPON_CAT[WT.MarksmanBow] = 'marksman'
    WEAPON_CAT[WT.MarksmanCrossbow] = 'marksman'
    WEAPON_CAT[WT.MarksmanThrown] = 'marksman'
    RANGED[WT.MarksmanBow] = true
    RANGED[WT.MarksmanCrossbow] = true
    RANGED[WT.MarksmanThrown] = true
end)

local AT = types.Armor.TYPE
local ARMOR_SLOT, ARMOR_GMST = {}, {}
pcall(function()
    local function s(t, slot, g) ARMOR_SLOT[t] = slot; ARMOR_GMST[t] = g end
    s(AT.Helmet, 'helmet', 'iHelmWeight')
    s(AT.Cuirass, 'cuirass', 'iCuirassWeight')
    s(AT.LPauldron, 'pauldrons', 'iPauldronWeight')
    s(AT.RPauldron, 'pauldrons', 'iPauldronWeight')
    s(AT.Greaves, 'greaves', 'iGreavesWeight')
    s(AT.Boots, 'boots', 'iBootsWeight')
    s(AT.LGauntlet, 'gauntlets', 'iGauntletWeight')
    s(AT.RGauntlet, 'gauntlets', 'iGauntletWeight')
    s(AT.LBracer, 'gauntlets', 'iGauntletWeight')
    s(AT.RBracer, 'gauntlets', 'iGauntletWeight')
    s(AT.Shield, 'shield', 'iShieldWeight')
end)
local DEFAULT_ARMOR_W = { iHelmWeight = 5, iCuirassWeight = 30, iPauldronWeight = 10, iGreavesWeight = 15,
                          iBootsWeight = 20, iGauntletWeight = 5, iShieldWeight = 15 }

local function armorClass(r)
    local g = ARMOR_GMST[r.type]
    local w = gmst(g or 'iCuirassWeight', DEFAULT_ARMOR_W[g] or 30)
    if r.weight <= w * gmst('fLightMaxMod', 0.6) + 0.0005 then return 'light' end
    if r.weight <= w * gmst('fMedMaxMod', 0.9) + 0.0005 then return 'medium' end
    return 'heavy'
end

local function armorSkillFactor(wc)
    local f = 1
    pcall(function()
        local v = types.NPC.stats.skills[wc .. 'armor'](self).modified
        f = v / gmst('iBaseArmorSkill', 30)
    end)
    return f
end

local CT = types.Clothing.TYPE
local CLOTH_CAT = {}
pcall(function()
    CLOTH_CAT[CT.Ring] = 'rings'
    CLOTH_CAT[CT.Amulet] = 'amulets'
    CLOTH_CAT[CT.Belt] = 'belts'
end)

-- returns { score, slot, text } or nil
local scoreCache = {}
local function scoreItem(t, id)
    local key = t .. '|' .. id
    if scoreCache[key] then return scoreCache[key] end
    local r = getRecord(t, id)
    if not r then return nil end
    local noEnch = setting('ignoreEnchant', false)
    local res
    if t == 'WEAP' then
        local cat = WEAPON_CAT[r.type]
        if not cat then return nil end
        local dmg
        if RANGED[r.type] then dmg = r.chopMaxDamage
        else dmg = (r.chopMaxDamage + r.slashMaxDamage + r.thrustMaxDamage) / 3 end
        local reach = r.reach or 1
        local base = dmg * r.speed * (1 + 0.1 * (reach - 1))
        local es, el = 0, nil
        if not noEnch then es, el = enchantScore(r.enchant) end
        local text = string.format('dmg %s x speed %.2f%s = %s', fmt(dmg), r.speed,
            math.abs(reach - 1) > 0.01 and string.format(' (reach %.1f)', reach) or '', fmt(base))
        if el then text = text .. string.format('  + ench %s (%s)', fmt(ENCH_WEIGHT * es), el) end
        res = { score = base + ENCH_WEIGHT * es, slot = 'w_' .. cat, text = text }
    elseif t == 'ARMO' then
        local slot = ARMOR_SLOT[r.type]
        if not slot then return nil end
        local wc = armorClass(r)
        local f = armorSkillFactor(wc)
        local ar = r.baseArmor * f
        local es, el = 0, nil
        if not noEnch then es, el = enchantScore(r.enchant) end
        local text = string.format('AR %d x %s skill %.2f = %s', math.floor(r.baseArmor or 0), wc, f, fmt(ar))
        if el then text = text .. string.format('  + ench %s (%s)', fmt(ENCH_WEIGHT * es), el) end
        res = { score = ar + ENCH_WEIGHT * es, slot = 'a_' .. slot, text = text, wc = wc }
    elseif t == 'CLOT' then
        local es, el = enchantScore(r.enchant)
        res = { score = es, slot = 's_' .. (CLOTH_CAT[r.type] or 'clothing'), text = 'ench ' .. fmt(es) .. (el and (' (' .. el .. ')') or '') }
    elseif t == 'BOOK' then
        local it = ITEMS[id]
        if it and it.sp then
            local sp
            pcall(function() sp = core.magic.spells.records[it.sp] end)
            local s, l = 0, '?'
            if sp then s, l = effectsScore(sp.effects, false) end
            res = { score = s, slot = 'spellbooks', text = 'teaches ' .. ((sp and sp.name) or it.sp) .. ': ' .. l
                    .. (it.int and ('  (needs Intelligence ' .. it.int .. ')') or ''), spell = sp }
        else
            local es, el = enchantScore(r.enchant, true)
            res = { score = es, slot = 'scrolls', text = 'spell ' .. fmt(es) .. (el and (' (' .. el .. ')') or '') }
        end
    elseif t == 'INGR' then
        local names = {}
        pcall(function()
            for _, e in ipairs(r.effects or {}) do
                local mg = e.effect
                if not mg then pcall(function() mg = core.magic.effects.records[e.id] end) end
                local n = (mg and mg.name) or tostring(e.id)
                if e.affectedSkill then n = n .. ' ' .. e.affectedSkill end
                if e.affectedAttribute then n = n .. ' ' .. e.affectedAttribute end
                names[#names + 1] = n
            end
        end)
        res = { score = 0, slot = 'ingredients', text = table.concat(names, ', ') }
    end
    if res then res.name = r.name or id end
    scoreCache[key] = res
    return res
end

-- the player's best owned item per slot (equipped or carried)
local bestOwned
local function computeBestOwned()
    local best = {}
    local inv = types.Actor.inventory(self)
    local function scan(T, t)
        local ok, list = pcall(function() return inv:getAll(T) end)
        if not ok then return end
        for _, o in ipairs(list) do
            local s = scoreItem(t, o.recordId)
            if s and s.slot and (not best[s.slot] or s.score > best[s.slot].score) then
                best[s.slot] = { score = s.score, name = s.name }
            end
        end
    end
    scan(types.Weapon, 'WEAP')
    scan(types.Armor, 'ARMO')
    scan(types.Clothing, 'CLOT')
    scan(types.Book, 'BOOK')
    bestOwned = best
    return best
end

local GREEN = util.color.rgb(0.45, 0.9, 0.45)
local YELLOW = util.color.rgb(0.95, 0.85, 0.35)
local RED = util.color.rgb(0.95, 0.45, 0.4)
local WHITE = util.color.rgb(0.93, 0.91, 0.86)
local GREY = util.color.rgb(0.62, 0.62, 0.6)
local GOLD = util.color.rgb(0.87, 0.72, 0.42)
local BLUE = util.color.rgb(0.66, 0.74, 0.80)
local LINK = util.color.rgb(0.95, 0.80, 0.45)

local function compareColor(score, slot)
    local b = bestOwned and bestOwned[slot]
    if not b or b.score <= 0 then return GREEN, 'you have nothing in this slot' end
    if score > b.score * 1.05 then return GREEN, 'better than your ' .. b.name end
    if score >= b.score * 0.95 then return YELLOW, 'about equal to your ' .. b.name end
    return RED, 'worse than your ' .. b.name
end

---------------------------------------------------------------------------
-- categories
---------------------------------------------------------------------------
local CAT = {}       -- category -> list of ids
local UNIQUES = {}
for id, it in pairs(ITEMS) do
    if it.c then
        CAT[it.c] = CAT[it.c] or {}
        table.insert(CAT[it.c], id)
    end
    if it.u or it.d then UNIQUES[#UNIQUES + 1] = id end
end

local listCache = {}
local function rankedList(cat)
    if listCache[cat] then return listCache[cat] end
    local ids = (cat == 's_unique') and UNIQUES or (CAT[cat] or {})
    local out = {}
    for _, id in ipairs(ids) do
        local it = ITEMS[id]
        if it and pluginLoaded(it.p) then
            local sc = scoreItem(it.t, id)
            if sc and #visibleSources(id) > 0 then
                out[#out + 1] = { id = id, it = it, sc = sc }
            end
        end
    end
    table.sort(out, function(a, b)
        if a.sc.score ~= b.sc.score then return a.sc.score > b.sc.score end
        return a.sc.name < b.sc.name
    end)
    listCache[cat] = out
    return out
end

local function invalidate()
    listCache = {}
    scoreCache = {}
    CLS = nil
end

---------------------------------------------------------------------------
-- tracking
---------------------------------------------------------------------------
local tracked = {}       -- saved list of { id, t, name, cid, ext, x, y, z, cont, where, base, done, doneAt, setName }
local lastSig

local function invCount(id)
    local ok, n = pcall(function() return types.Actor.inventory(self):countOf(id) end)
    return ok and n or 0
end

local function isTracked(id)
    for i, e in ipairs(tracked) do if e.id == id then return i end end
    return nil
end

local function cellIndexOf(e)
    if e.ext then return nil end
    return CELL_BY_ID[e.cid or '']
end

local function entryFromSource(id, s)
    local c = CELLS[s.cell]
    return {
        cid = (c and not c.e) and c.id or nil,
        ext = (c and c.e) and true or false,
        cellName = c and c.n or '?',
        x = s.x, y = s.y, z = s.z, cont = s.cont, ci = s.cell,
        where = whereText(s), tags = tagText(s, ITEMS[id] and ITEMS[id].p),
    }
end

local function retarget(e)
    local preferFree = (e.t == 'INGR')
    local s = nearestSource(e.id, preferFree)
    if not s then return false end
    local info = entryFromSource(e.id, s)
    for k, v in pairs(info) do e[k] = v end
    return true
end

local function track(id, setName)
    if isTracked(id) then return true end
    if #tracked >= setting('maxTracked', 5) then
        ui.showMessage("Collector's Ledger: already tracking " .. #tracked .. ' items (see settings)')
        return false
    end
    local it = ITEMS[id]
    if not it then return false end
    local r = getRecord(it.t, id)
    local e = { id = id, t = it.t, name = (r and r.name) or id, base = invCount(id), setName = setName }
    if not retarget(e) then
        ui.showMessage("Collector's Ledger: no copy of " .. e.name .. ' left')
        return false
    end
    tracked[#tracked + 1] = e
    lastSig = nil
    return true
end

local function untrack(id)
    local i = isTracked(id)
    if i then table.remove(tracked, i) end
    lastSig = nil
end

local function blockItems()
    local items = {}
    for _, e in ipairs(tracked) do
        local text = 'Get ' .. e.name .. ' (' .. (e.cellName or '?') .. ')'
        local s = { cell = e.ci or cellIndexOf(e) or 0, x = e.x, y = e.y, z = e.z }
        local marker
        if e.ext then
            marker = { positions = { { cell = { isExterior = true }, position = { x = e.x, y = e.y, z = e.z } } } }
        else
            local ci = cellIndexOf(e)
            if ci then
                s.cell = ci
                marker = markerFor(e.id, s)
            else
                marker = { positions = { { cell = { isExterior = false, id = e.cid or '' }, position = { x = e.x, y = e.y, z = e.z } } } }
            end
        end
        items[#items + 1] = { text = text, where = (e.where or '') .. ((e.tags and e.tags ~= '') and (' [' .. e.tags .. ']') or ''),
                              done = e.done and true or false, marker = marker }
    end
    return items
end

local function sendBlock()
    local sig = ''
    for _, e in ipairs(tracked) do
        sig = sig .. e.id .. '@' .. tostring(e.cid) .. ':' .. tostring(e.x) .. ',' .. tostring(e.y) .. (e.done and '+' or '-') .. '|'
    end
    if sig == lastSig then return end
    lastSig = sig
    if #tracked == 0 then
        self:sendEvent('CO_RemoveCustomBlock', { id = BLOCK_ID })
    else
        self:sendEvent('CO_SetCustomBlock', { id = BLOCK_ID, name = BLOCK_NAME, color = BLOCK_COLOR, items = blockItems() })
    end
end

local function updateTracking()
    local now = core.getSimulationTime()
    local delay = setting('doneDelay', 30)
    local i = 1
    while i <= #tracked do
        local e = tracked[i]
        if not e.done and invCount(e.id) > (e.base or 0) then
            e.done = true
            e.doneAt = now
            ui.showMessage("Collector's Ledger: got " .. e.name)
        end
        if e.done and e.doneAt and now - e.doneAt >= delay then
            table.remove(tracked, i)
        else
            i = i + 1
        end
    end
    sendBlock()
end

---------------------------------------------------------------------------
-- runtime check of the prebuilt index: are the items really there?
---------------------------------------------------------------------------
local CELL_SRC, EXT_SRC
local function buildIndex()
    CELL_SRC, EXT_SRC = {}, {}
    for id in pairs(ITEMS) do
        for _, s in ipairs(sourcesOf(id)) do
            local c = CELLS[s.cell]
            if c then
                if c.e then
                    local k = math.floor(s.x / 8192) .. ',' .. math.floor(s.y / 8192)
                    EXT_SRC[k] = EXT_SRC[k] or {}
                    table.insert(EXT_SRC[k], { id, s })
                else
                    CELL_SRC[s.cell] = CELL_SRC[s.cell] or {}
                    table.insert(CELL_SRC[s.cell], { id, s })
                end
            end
        end
    end
end

local function verifyLoaded()
    local cell = self.cell
    if not cell then return end
    if not CELL_SRC then buildIndex() end
    local cand = {}
    if cell.isExterior then
        local p = self.position
        local gx, gy = math.floor(p.x / 8192), math.floor(p.y / 8192)
        for dx = -1, 1 do
            for dy = -1, 1 do
                for _, e in ipairs(EXT_SRC[(gx + dx) .. ',' .. (gy + dy)] or {}) do
                    local s = e[2]
                    if (s.x - p.x) ^ 2 + (s.y - p.y) ^ 2 < 6000 ^ 2 then cand[#cand + 1] = e end
                end
            end
        end
    else
        local ci = CELL_BY_ID[lower(cell.id)] or CELL_BY_ID[lower(cell.name)]
        cand = (ci and CELL_SRC[ci]) or {}
    end
    if #cand == 0 then return end
    local want = {}
    for _, e in ipairs(cand) do want[e[1]] = true end
    local itemsAt = {}
    for _, o in ipairs(nearby.items) do
        local rid = o.recordId
        if want[rid] then
            itemsAt[rid] = itemsAt[rid] or {}
            table.insert(itemsAt[rid], o.position)
        end
    end
    local conts = nearby.containers
    local changed = false
    for _, e in ipairs(cand) do
        local id, s = e[1], e[2]
        local key = srcKey(id, s)
        if not stale[key] and pluginLoaded(s.plugin) then
            local found
            if s.body then
                local aobj
                for _, a in ipairs(nearby.actors) do
                    local q = a.position
                    if a.recordId ~= self.recordId and math.abs(q.x - s.x) < 160 and math.abs(q.y - s.y) < 160 and math.abs(q.z - s.z) < 256 then
                        local ok, n = pcall(function() return types.Actor.inventory(a):countOf(id) end)
                        if ok and n > 0 then aobj = a break end
                    end
                end
                found = aobj ~= nil
            elseif s.inCont then
                local cobj
                for _, c in ipairs(conts) do
                    local q = c.position
                    if math.abs(q.x - s.x) < 64 and math.abs(q.y - s.y) < 64 and math.abs(q.z - s.z) < 96 then cobj = c break end
                end
                if not cobj then
                    found = false
                else
                    local ok, res = pcall(function()
                        local inv = types.Container.inventory(cobj)
                        if inv.isResolved and not inv:isResolved() then return true end   -- not opened yet: trust the data
                        return inv:countOf(id) > 0
                    end)
                    found = (not ok) or res
                end
            else
                found = false
                for _, q in ipairs(itemsAt[id] or {}) do
                    if math.abs(q.x - s.x) < 96 and math.abs(q.y - s.y) < 96 and math.abs(q.z - s.z) < 160 then found = true break end
                end
            end
            if not found then
                stale[key] = true
                changed = true
            end
        end
    end
    if changed then
        listCache = {}
        -- tracked copies that vanished: go for the next nearest one
        for _, t in ipairs(tracked) do
            if not t.done then
                local still = false
                for _, s in ipairs(visibleSources(t.id)) do
                    if s.x == t.x and s.y == t.y and (CELLS[s.cell] and CELLS[s.cell].id) == t.cid then still = true break end
                end
                if not still then
                    if not retarget(t) then t.where = 'no copy left'; t.tags = '' end
                end
            end
        end
        lastSig = nil
    end
end

---------------------------------------------------------------------------
-- menu
---------------------------------------------------------------------------
local element
local state = { tab = 'weapons', sub = 'longblade', wc = 'heavy', slot = 'cuirass', page = 1, ingSort = 'near', setW = 'all' }
local WIN_W, WIN_H = 1000, 720
local LINE = 17
local GAP = 3

local function cut(s, width, size)
    s = tostring(s or '')
    local maxc = math.floor(width / ((size or 15) * 0.5))
    if #s > maxc then s = s:sub(1, math.max(1, maxc - 3)) .. '...' end
    return s
end

local clicks, clickN = {}, 0
local FOCUS = util.color.rgb(1.0, 0.93, 0.62)

local function T(text, x, y, w, color, size, onClick)
    size = size or 15
    local t = {
        type = ui.TYPE.Text,
        props = {
            text = cut(text, w, size),
            textSize = size,
            textColor = color or WHITE,
            textShadow = true,
            textShadowColor = util.color.rgb(0, 0, 0),
            autoSize = false,
            position = util.vector2(x, y),
            size = util.vector2(w, size + 4),
        },
    }
    if onClick then
        t.events = { mouseClick = async:callback(function() onClick() end) }
        -- controller focus: every clickable gets an index; the focused one is highlighted
        clickN = clickN + 1
        clicks[clickN] = { fn = onClick, x = x, y = y }
        if clickN == (state.focus or 1) then
            t.props.text = cut('> ' .. tostring(text or ''), w + 16, size)
            t.props.size = util.vector2(w + 16, size + 4)
            t.props.textColor = FOCUS
        end
    end
    return t
end

local redraw

local function tabsRow(children, y, list, current, onPick, x0)
    local x = x0 or 14
    for _, e in ipairs(list) do
        local label = e[2]
        local w = #label * 8 + 18
        local sel = (e[1] == current)
        children[#children + 1] = T(sel and ('[' .. label .. ']') or label, x, y, w, sel and GOLD or BLUE, 16, function()
            onPick(e[1]); redraw()
        end)
        x = x + w + 6
    end
end

local WEAPON_TABS = { { 'longblade', 'Long Blade' }, { 'shortblade', 'Short Blade' }, { 'axe', 'Axe' }, { 'blunt', 'Blunt' },
                      { 'spear', 'Spear' }, { 'marksman', 'Marksman' } }
local WC_TABS = { { 'light', 'Light' }, { 'medium', 'Medium' }, { 'heavy', 'Heavy' } }
local SLOT_TABS = { { 'helmet', 'Helmet' }, { 'cuirass', 'Cuirass' }, { 'pauldrons', 'Pauldrons' },
                    { 'gauntlets', 'Gauntlets/Bracers' }, { 'greaves', 'Greaves' }, { 'boots', 'Boots' }, { 'shield', 'Shield' } }
local SPECIAL_TABS = { { 's_unique', 'Artifacts & Uniques' }, { 's_rings', 'Rings' }, { 's_amulets', 'Amulets' },
                       { 's_belts', 'Belts' }, { 's_clothing', 'Clothing' } }
local SET_TABS = { { 'all', 'All' }, { 'light', 'Light' }, { 'medium', 'Medium' }, { 'heavy', 'Heavy' } }

local function mainTabs()
    local t = { { 'weapons', 'Weapons' }, { 'armor', 'Armor' }, { 'sets', 'Armor Sets' }, { 'special', 'Special' },
                { 'scrolls', 'Scrolls' } }
    if CAT.spellbooks and #CAT.spellbooks > 0 then t[#t + 1] = { 'spellbooks', 'Spell Books' } end
    t[#t + 1] = { 'ingredients', 'Ingredients' }
    t[#t + 1] = { 'tracked', 'Tracked (' .. #tracked .. ')' }
    return t
end

local function currentCat()
    local tab = state.tab
    if tab == 'weapons' then return 'w_' .. state.sub end
    if tab == 'armor' then return 'a_' .. state.wc .. '_' .. state.slot end
    if tab == 'special' then return state.special or 's_unique' end
    if tab == 'scrolls' then return 'scrolls' end
    if tab == 'spellbooks' then return 'spellbooks' end
    return nil
end

local function trackButton(children, id, x, y, setName)
    local on = isTracked(id) ~= nil
    children[#children + 1] = T(on and '[Untrack]' or '[Track]', x, y, 100, on and GREY or LINK, 15, function()
        if isTracked(id) then untrack(id) else track(id, setName) end
        updateTracking()
        redraw()
    end)
end

local function pager(children, y, total, per)
    local pages = math.max(1, math.ceil(total / per))
    if state.page > pages then state.page = pages end
    if pages <= 1 then return end
    children[#children + 1] = T('< Prev', WIN_W - 300, y, 70, state.page > 1 and LINK or GREY, 15, function()
        if state.page > 1 then state.page = state.page - 1 end
        redraw()
    end)
    children[#children + 1] = T('page ' .. state.page .. '/' .. pages, WIN_W - 220, y, 110, GREY, 15)
    children[#children + 1] = T('Next >', WIN_W - 100, y, 70, state.page < pages and LINK or GREY, 15, function()
        if state.page < pages then state.page = state.page + 1 end
        redraw()
    end)
end

local function perPage(y0)
    local avail = WIN_H - y0 - 30
    return math.max(3, math.floor(avail / (3 * LINE + GAP)))
end

local function drawItemList(children, y0, cat)
    local list = rankedList(cat)
    local topN = math.min(#list, setting('topN', 10))
    local per = perPage(y0)
    pager(children, y0 - 24, topN, per)
    if topN == 0 then
        children[#children + 1] = T('Nothing placed in the world for this category (with the loaded plugins).', 20, y0, WIN_W - 40, GREY)
        return
    end
    local y = y0
    local first = (state.page - 1) * per + 1
    for i = first, math.min(topN, first + per - 1) do
        local e = list[i]
        local col, why = WHITE, ''
        if cat ~= 'spellbooks' then col, why = compareColor(e.sc.score, e.sc.slot) end
        if cat == 'spellbooks' and e.it.int then
            local intv = 0
            pcall(function() intv = types.Actor.stats.attributes.intelligence(self).modified end)
            col = (intv >= e.it.int) and GREEN or RED
            why = (intv >= e.it.int) and 'you can learn it' or ('Intelligence ' .. intv .. ' is too low')
        end
        local s, d, n = nearestSource(e.id, false)
        local head = string.format('%d. %s   score %s', i, e.sc.name, fmt(e.sc.score))
        if e.sc.wc and cat == 's_unique' then head = head .. '  (' .. e.sc.wc .. ' armor)' end
        children[#children + 1] = T(head, 14, y, 560, col, 16)
        children[#children + 1] = T(why, 580, y, 300, col, 14)
        trackButton(children, e.id, WIN_W - 110, y, nil)
        local line2 = e.sc.text
        if e.it.d then line2 = e.it.d .. '   ' .. line2 end
        children[#children + 1] = T(line2, 34, y + LINE, WIN_W - 50, GREY, 14)
        local line3 = string.format('%d %s, nearest %s: %s', n, n == 1 and 'copy' or 'copies', distCells(d), s and whereText(s) or '?')
        if s then line3 = line3 .. '   [' .. tagText(s, e.it.p) .. ']' end
        children[#children + 1] = T(line3, 34, y + 2 * LINE, WIN_W - 50, BLUE, 14)
        y = y + 3 * LINE + GAP
    end
end

-- armor sets ---------------------------------------------------------------
local SET_SLOT_LABEL = { helmet = 'helm', cuirass = 'cuirass', pauldron_l = 'L pauldron', pauldron_r = 'R pauldron',
                         greaves = 'greaves', boots = 'boots', gauntlet_l = 'L gauntlet', gauntlet_r = 'R gauntlet', shield = 'shield' }
local SET_ORDER = { 'helmet', 'cuirass', 'pauldron_l', 'pauldron_r', 'gauntlet_l', 'gauntlet_r', 'greaves', 'boots', 'shield' }
local SLOT_GROUP = { helmet = 'helmet', cuirass = 'cuirass', pauldron_l = 'pauldrons', pauldron_r = 'pauldrons', greaves = 'greaves',
                     boots = 'boots', gauntlet_l = 'gauntlets', gauntlet_r = 'gauntlets', shield = 'shield' }

local setCache
local function setList()
    if setCache then return setCache end
    local out = {}
    for _, st in ipairs(DATA.sets or {}) do
        local s = { m = st.m, w = st.w, slots = {}, total = 0, owned = 0, pieces = 0, mine = 0 }
        for _, slot in ipairs(SET_ORDER) do
            local ids = st.slots and st.slots[slot]
            if ids then
                local best, bestSc, owns, copies = nil, nil, false, 0
                for _, id in ipairs(ids) do
                    local it = ITEMS[id]
                    if it and pluginLoaded(it.p) then
                        local sc = scoreItem('ARMO', id)
                        local n = #visibleSources(id)
                        if invCount(id) > 0 then owns = true end
                        if sc and n > 0 then
                            copies = copies + n
                            if not bestSc or sc.score > bestSc.score then best, bestSc = id, sc end
                        end
                    end
                end
                if best then
                    s.slots[#s.slots + 1] = { slot = slot, id = best, ids = ids, sc = bestSc, owns = owns, copies = copies }
                    s.total = s.total + bestSc.score
                    s.pieces = s.pieces + 1
                    if owns then s.owned = s.owned + 1 end
                    local b = bestOwned and bestOwned['a_' .. SLOT_GROUP[slot]]
                    s.mine = s.mine + (b and b.score or 0)
                end
            end
        end
        if s.pieces >= 5 then out[#out + 1] = s end
    end
    table.sort(out, function(a, b) return a.total > b.total end)
    setCache = out
    return out
end

local function nearestMissing(s)
    local res = {}
    for _, sl in ipairs(s.slots) do
        if not sl.owns then
            local bestS, bestD, bestId
            for _, id in ipairs(sl.ids) do
                local it = ITEMS[id]
                if it and pluginLoaded(it.p) then
                    local src, d = nearestSource(id, false)
                    if src and (not bestS or (d or 1e12) < (bestD or 1e12)) then bestS, bestD, bestId = src, d, id end
                end
            end
            if bestId then res[#res + 1] = { slot = sl.slot, id = bestId, s = bestS, d = bestD } end
        end
    end
    table.sort(res, function(a, b) return (a.d or 1e12) < (b.d or 1e12) end)
    return res
end

local function drawSets(children, y0)
    local all = setList()
    local list = {}
    for _, s in ipairs(all) do
        if state.setW == 'all' or s.w == state.setW then list[#list + 1] = s end
    end
    local topN = math.min(#list, setting('topN', 10))
    local per = perPage(y0)
    pager(children, y0 - 24, topN, per)
    local y = y0
    local first = (state.page - 1) * per + 1
    for i = first, math.min(topN, first + per - 1) do
        local s = list[i]
        local col = GREEN
        if s.mine > 0 then
            if s.total > s.mine * 1.05 then col = GREEN elseif s.total >= s.mine * 0.95 then col = YELLOW else col = RED end
        end
        children[#children + 1] = T(string.format('%d. %s set (%s)   %d pieces exist, you own %d   score %s (yours %s)',
            i, s.m, s.w, s.pieces, s.owned, fmt(s.total), fmt(s.mine)), 14, y, WIN_W - 180, col, 16)
        children[#children + 1] = T('[Track missing]', WIN_W - 150, y, 140, LINK, 15, function()
            local miss = nearestMissing(s)
            local added = 0
            for _, m in ipairs(miss) do
                if not isTracked(m.id) and #tracked < setting('maxTracked', 5) then
                    if track(m.id, s.m) then added = added + 1 end
                end
            end
            local left = #miss - added
            ui.showMessage(string.format("Collector's Ledger: tracking %d missing %s pieces%s", added, s.m,
                left > 0 and string.format(' (%d more not tracked: limit)', left) or ''))
            updateTracking()
            redraw()
        end)
        local parts = {}
        for _, sl in ipairs(s.slots) do
            parts[#parts + 1] = SET_SLOT_LABEL[sl.slot] .. ' ' .. sl.copies .. (sl.owns and ' (have)' or '')
        end
        children[#children + 1] = T('copies in the world: ' .. table.concat(parts, ', '), 34, y + LINE, WIN_W - 50, GREY, 14)
        local miss = nearestMissing(s)
        local m = miss[1]
        local line3 = m and string.format('nearest missing: %s - %s: %s [%s]', SET_SLOT_LABEL[m.slot], distCells(m.d), whereText(m.s), tagText(m.s, ITEMS[m.id].p))
            or 'you have every piece'
        children[#children + 1] = T(line3, 34, y + 2 * LINE, WIN_W - 50, BLUE, 14)
        y = y + 3 * LINE + GAP
    end
    if topN == 0 then children[#children + 1] = T('No armor sets found.', 20, y0, 400, GREY) end
end

-- ingredients --------------------------------------------------------------
local ingCache
local function ingredientList()
    if ingCache then return ingCache end
    local out = {}
    for _, id in ipairs(CAT.ingredients or {}) do
        local it = ITEMS[id]
        if it and pluginLoaded(it.p) then
            local r = getRecord('INGR', id)
            if r then
                local s, d, n = nearestSource(id, true)
                if s then out[#out + 1] = { id = id, it = it, name = r.name or id, s = s, d = d, n = n } end
            end
        end
    end
    ingCache = out
    return out
end

local function drawIngredients(children, y0)
    local list = ingredientList()
    local sorted = {}
    for i, e in ipairs(list) do sorted[i] = e end
    if state.ingSort == 'near' then
        table.sort(sorted, function(a, b) return (a.d or 1e12) < (b.d or 1e12) end)
    else
        table.sort(sorted, function(a, b) return a.name < b.name end)
    end
    local per = perPage(y0)
    pager(children, y0 - 24, #sorted, per)
    local y = y0
    local first = (state.page - 1) * per + 1
    for i = first, math.min(#sorted, first + per - 1) do
        local e = sorted[i]
        local sc = scoreItem('INGR', e.id)
        local free = not e.s.owned and (e.s.lock or 0) <= 0
        children[#children + 1] = T(string.format('%d. %s   (%d sources, nearest %s%s)', i, e.name, e.n, distCells(e.d),
            free and '' or ', no free source'), 14, y, WIN_W - 130, free and WHITE or YELLOW, 16)
        trackButton(children, e.id, WIN_W - 110, y)
        children[#children + 1] = T(sc and sc.text or '', 34, y + LINE, WIN_W - 50, GREY, 14)
        children[#children + 1] = T(whereText(e.s) .. '   [' .. tagText(e.s, e.it.p) .. ']', 34, y + 2 * LINE, WIN_W - 50, BLUE, 14)
        y = y + 3 * LINE + GAP
    end
end

-- tracked ------------------------------------------------------------------
local function drawTracked(children, y0)
    local y = y0
    if #tracked == 0 then
        children[#children + 1] = T('Nothing tracked. Use [Track] on any entry (up to ' .. setting('maxTracked', 5) .. ').', 20, y, WIN_W - 40, GREY)
        return
    end
    for i, e in ipairs(tracked) do
        children[#children + 1] = T(string.format('%d. %s%s%s', i, e.done and 'X ' or '', e.name, e.setName and ('  (' .. e.setName .. ' set)') or ''),
            14, y, WIN_W - 260, e.done and GREY or WHITE, 16)
        children[#children + 1] = T('[Nearest]', WIN_W - 220, y, 90, LINK, 15, function()
            retarget(e); lastSig = nil; updateTracking(); redraw()
        end)
        children[#children + 1] = T('[Untrack]', WIN_W - 110, y, 100, LINK, 15, function()
            untrack(e.id); updateTracking(); redraw()
        end)
        children[#children + 1] = T((e.where or '') .. '   [' .. (e.tags or '') .. ']', 34, y + LINE, WIN_W - 50, BLUE, 14)
        y = y + 2 * LINE + 8
    end
end

local function buildLayout()
    local children = {}
    clicks, clickN = {}, 0
    local cls = classInfo()
    children[#children + 1] = T("Collector's Ledger", 14, 8, 300, GOLD, 20)
    children[#children + 1] = T('class: ' .. tostring(cls.name) .. (setting('ignoreEnchant', false) and '   (enchantments ignored)' or ''),
        330, 12, 420, GREY, 14)
    children[#children + 1] = T('[Close]', WIN_W - 90, 8, 80, LINK, 16, function()
        pcall(function() I.UI.removeMode('Interface') end)
    end)
    tabsRow(children, 40, mainTabs(), state.tab, function(v) state.tab = v; state.page = 1 end)
    local y = 68
    if state.tab == 'weapons' then
        tabsRow(children, y, WEAPON_TABS, state.sub, function(v) state.sub = v; state.page = 1 end)
    elseif state.tab == 'armor' then
        tabsRow(children, y, WC_TABS, state.wc, function(v) state.wc = v; state.page = 1 end)
        tabsRow(children, y + 24, SLOT_TABS, state.slot, function(v) state.slot = v; state.page = 1 end)
    elseif state.tab == 'special' then
        tabsRow(children, y, SPECIAL_TABS, state.special or 's_unique', function(v) state.special = v; state.page = 1 end)
    elseif state.tab == 'sets' then
        tabsRow(children, y, SET_TABS, state.setW, function(v) state.setW = v; state.page = 1 end)
    elseif state.tab == 'ingredients' then
        tabsRow(children, y, { { 'near', 'Nearest first' }, { 'name', 'By name' } }, state.ingSort,
            function(v) state.ingSort = v; state.page = 1 end)
    end
    local y0 = (state.tab == 'armor') and 146 or 122
    if state.tab == 'sets' then
        drawSets(children, y0)
    elseif state.tab == 'ingredients' then
        drawIngredients(children, y0)
    elseif state.tab == 'tracked' then
        drawTracked(children, y0)
    else
        drawItemList(children, y0, currentCat())
    end
    children[#children + 1] = T('Green: >5% better than your best (equipped or carried), yellow: within 5%, red: worse.  '
        .. 'Only items placed in the world or fixed in containers; OWNED = stealing is a crime.', 14, WIN_H - 26, WIN_W - 28, GREY, 13)
    return {
        layer = 'Windows',
        template = I.MWUI.templates.boxSolidThick,
        props = {
            relativePosition = util.vector2(0.5, 0.5),
            anchor = util.vector2(0.5, 0.5),
        },
        content = ui.content {
            {
                type = ui.TYPE.Widget,
                props = { size = util.vector2(WIN_W, WIN_H) },
                content = ui.content(children),
            },
        },
    }
end

redraw = function()
    if not element then return end
    local ok, layout = pcall(buildLayout)
    if ok and clickN > 0 and (state.focus or 1) > clickN then
        state.focus = clickN
        ok, layout = pcall(buildLayout)
    end
    if not ok then
        print("[Collector's Ledger] menu error: " .. tostring(layout))
        return
    end
    element.layout = layout
    element:update()
end

local function closeMenu()
    if element then
        element:destroy()
        element = nil
    end
end

local function openMenu()
    if element then return end
    pcall(function()
        local size = ui.screenSize()
        WIN_W = math.min(1000, math.floor(size.x - 40))
        WIN_H = math.min(720, math.floor(size.y - 40))
    end)
    invalidate()
    ingCache = nil
    setCache = nil
    pcall(computeBestOwned)
    local ok, layout = pcall(buildLayout)
    if not ok then
        print("[Collector's Ledger] menu error: " .. tostring(layout))
        return
    end
    element = ui.create(layout)
    state.focus = 2   -- first tab, not [Close]
    redraw()
    pcall(function() I.UI.setMode('Interface', { windows = {} }) end)
end

local function toggleMenu()
    if element then
        pcall(function() I.UI.removeMode('Interface') end)
        closeMenu()
        return
    end
    local mode
    pcall(function() mode = I.UI.getMode() end)
    if mode ~= nil then return end   -- don't open on top of dialogs / inventory / console
    openMenu()
end

if triggerOk then
    pcall(function() input.registerTriggerHandler(TRIGGER, async:callback(toggleMenu)) end)
end

-- default key L: written once into the engine's binding storage (changeable in the settings page)
local seeded = false
local function seedBinding()
    if seeded or not triggerOk then return end
    seeded = true
    pcall(function()
        local st = storage.playerSection('CollectorsLedgerState')
        if st:get('bindingSeeded') then return end
        local bs = storage.playerSection('OMWInputBindings')
        if bs:get(BINDING_ID) == nil then
            bs:set(BINDING_ID, { device = 'keyboard', button = input.KEY.L, type = 'trigger', key = TRIGGER })
        end
        st:set('bindingSeeded', true)
    end)
end

---------------------------------------------------------------------------
-- engine handlers
---------------------------------------------------------------------------
local timer, verifyTimer = 0, 0
local lastCellKey

return {
    eventHandlers = {
        UiModeChanged = function(data)
            if element and data and data.newMode ~= 'Interface' then closeMenu() end
        end,
    },
    engineHandlers = {
        onFrame = function()
            if not seeded then seedBinding() end
        end,
        onKeyPress = function(key)
            -- fallback when the trigger API is unavailable
            if not triggerOk and key.code == input.KEY.L then toggleMenu() end
        end,
        onControllerButtonPress = function(id)
            local B = input.CONTROLLER_BUTTON
            if not element then
                -- D-pad down opens the Ledger during normal play
                if id == B.DPadDown then toggleMenu() end
                return
            end
            -- inside the Ledger: D-pad moves, A selects, LB/RB switch tabs, B closes
            local f = state.focus or 1
            local cur = clicks[f]
            local function rowJump(dir)
                if not cur then return 1 end
                local best, bestRowY, bestDx
                for i, c in ipairs(clicks) do
                    local dy = (c.y - cur.y) * dir
                    if dy > 4 then
                        if not bestRowY or (c.y - bestRowY) * dir < -4 then
                            bestRowY = c.y; best = i; bestDx = math.abs(c.x - cur.x)
                        elseif math.abs(c.y - bestRowY) <= 4 and math.abs(c.x - cur.x) < bestDx then
                            best = i; bestDx = math.abs(c.x - cur.x)
                        end
                    end
                end
                return best or f
            end
            if id == B.DPadDown then state.focus = rowJump(1)
            elseif id == B.DPadUp then state.focus = rowJump(-1)
            elseif id == B.DPadRight then state.focus = math.min(clickN, f + 1)
            elseif id == B.DPadLeft then state.focus = math.max(1, f - 1)
            elseif id == B.A then
                if cur then cur.fn() end
                return
            elseif id == B.B or id == B.Back then
                toggleMenu(); return
            elseif id == B.LeftShoulder or id == B.RightShoulder then
                local tabs = mainTabs()
                local idx = 1
                for i, t in ipairs(tabs) do if t[1] == state.tab then idx = i end end
                idx = idx + ((id == B.RightShoulder) and 1 or -1)
                if idx < 1 then idx = #tabs elseif idx > #tabs then idx = 1 end
                state.tab = tabs[idx][1]; state.page = 1; state.focus = 1
            else
                return
            end
            redraw()
        end,
        onUpdate = function(dt)
            timer = timer + dt
            verifyTimer = verifyTimer + dt
            local cell = self.cell
            if cell and cell.isExterior then lastExt = { x = self.position.x, y = self.position.y } end
            local ck = cell and (cell.isExterior and 'ext' or lower(cell.id)) or ''
            if ck ~= lastCellKey or verifyTimer > 5 then
                lastCellKey = ck
                verifyTimer = 0
                local ok, err = pcall(verifyLoaded)
                if not ok then print("[Collector's Ledger] verify: " .. tostring(err)) end
            end
            if timer >= 1 then
                timer = 0
                local ok, err = pcall(updateTracking)
                if not ok then print("[Collector's Ledger] tracking: " .. tostring(err)) end
            end
        end,
        onSave = function()
            local t = {}
            for _, e in ipairs(tracked) do
                t[#t + 1] = { id = e.id, t = e.t, name = e.name, cid = e.cid, ext = e.ext, cellName = e.cellName,
                              x = e.x, y = e.y, z = e.z, cont = e.cont, where = e.where, tags = e.tags, base = e.base,
                              done = e.done, doneAt = e.doneAt, setName = e.setName }
            end
            return { version = 1, tracked = t, stale = stale, lastExt = lastExt }
        end,
        onLoad = function(data)
            tracked = (data and data.tracked) or {}
            stale = (data and data.stale) or {}
            lastExt = data and data.lastExt
            for _, e in ipairs(tracked) do e.ci = nil end   -- cell indices may differ after a data rebuild
            lastSig = nil
            invalidate()
        end,
        onInit = function()
            tracked, stale = {}, {}
            lastSig = nil
        end,
    },
}
